function fetchNotifCount(){fetch("/api/notifications?action=unread_count").then(t=>t.json()).then(t=>{var e=document.querySelector(".notif-badge");e&&(0<(t=t.unread||t.count||0)?(e.textContent=99<t?"99+":t,e.style.display="flex"):e.style.display="none")}).catch(()=>{})}function insertMacro(t,e){var n,o,t=document.getElementById(t);t&&(n=t.selectionStart,t.value=(o=t.value).slice(0,n)+e+o.slice(n),t.focus(),t.setSelectionRange(n+e.length,n+e.length))}document.addEventListener("DOMContentLoaded",function(){var t=document.querySelector(".user-menu");let e=document.querySelector(".dropdown-menu");t&&e&&(t.addEventListener("click",function(t){t.stopPropagation(),e.classList.toggle("show")}),document.addEventListener("click",function(){e.classList.remove("show")})),document.querySelectorAll(".alert[data-auto-hide]").forEach(function(t){setTimeout(function(){t.style.transition="opacity .4s",t.style.opacity="0",setTimeout(()=>t.remove(),400)},4e3)}),document.querySelectorAll("[data-copy]").forEach(function(e){e.addEventListener("click",function(){var t=document.getElementById(e.dataset.copy);t&&navigator.clipboard.writeText(t.value||t.textContent).then(function(){let t=e.textContent;e.textContent="Copied!",setTimeout(()=>e.textContent=t,2e3)})})}),document.querySelectorAll("[data-confirm]").forEach(function(e){e.addEventListener("click",function(t){confirm(e.dataset.confirm)||t.preventDefault()})}),fetchNotifCount(),setInterval(fetchNotifCount,6e4)});